// A .docx from the office-writer model: a title, headings, paragraphs, lists and tables, with the
// styles and numbering parts Word and LibreOffice need to show them as such (ADR-0167 D6).
import { contentTypes, escapeXml, OOXML, relationships, XML_DECLARATION, zip } from './package.mjs';

const W = `${OOXML}/wordprocessingml/2006/main`;
const WORD = 'application/vnd.openxmlformats-officedocument.wordprocessingml';

/** A4 with 2.54 cm margins, in twentieths of a point; the text is 9,026 wide. */
const PAGE = { width: 11_906, height: 16_838, margin: 1_440 };
const TEXT_WIDTH = PAGE.width - 2 * PAGE.margin;

/** Runs of `text`, a line break kept as a `<w:br/>`. */
function runs(text, properties) {
  return String(text)
    .split(/\r\n|\r|\n/u)
    .map((line) => `<w:r>${properties}<w:t xml:space="preserve">${escapeXml(line)}</w:t></w:r>`)
    .join(`<w:r><w:br/></w:r>`);
}

function paragraph(text, { style = '', numbering = '', align = '', bold = false }) {
  const pStyle = style === '' ? '' : `<w:pStyle w:val="${style}"/>`;
  const jc = align === '' ? '' : `<w:jc w:val="${align}"/>`;
  const pPr = `${pStyle}${numbering}${jc}`;
  return `<w:p>${pPr === '' ? '' : `<w:pPr>${pPr}</w:pPr>`}${runs(text, bold ? '<w:rPr><w:b/></w:rPr>' : '')}</w:p>`;
}

function cell(value, width, bold) {
  const align = typeof value === 'number' ? 'right' : '';
  return `<w:tc><w:tcPr><w:tcW w:w="${width}" w:type="dxa"/></w:tcPr>${paragraph(value, { align, bold })}</w:tc>`;
}

/** A grid table at the text width, its header row repeated on every page, then an empty paragraph. */
function table({ header, rows }) {
  const columns = (header ?? rows[0]).length;
  const width = Math.floor(TEXT_WIDTH / columns);
  const row = (cells, bold) =>
    `<w:tr>${bold ? '<w:trPr><w:tblHeader/></w:trPr>' : ''}${cells.map((value) => cell(value, width, bold)).join('')}</w:tr>`;
  const grid = `<w:gridCol w:w="${width}"/>`.repeat(columns);
  return [
    `<w:tbl><w:tblPr><w:tblStyle w:val="TableGrid"/><w:tblW w:w="${width * columns}" w:type="dxa"/><w:tblLayout w:type="fixed"/></w:tblPr><w:tblGrid>${grid}</w:tblGrid>`,
    header === undefined ? '' : row(header, true),
    ...rows.map((cells) => row(cells, false)),
    '</w:tbl><w:p/>',
  ].join('');
}

const BULLETS = 1;

function body(model) {
  const lists = [];
  const blocks = model.blocks.map((block) => {
    if (block.type === 'heading') return paragraph(block.text, { style: `Heading${block.level}` });
    if (block.type === 'paragraph') return paragraph(block.text, {});
    if (block.type === 'table') return table(block);
    // Each numbered list is its own numbering instance, so it starts again at 1.
    const numId = block.ordered === true ? BULLETS + lists.push(block) : BULLETS;
    const numbering = `<w:numPr><w:ilvl w:val="0"/><w:numId w:val="${numId}"/></w:numPr>`;
    return block.items
      .map((item) => paragraph(item, { style: 'ListParagraph', numbering }))
      .join('');
  });
  const title = model.title === undefined ? '' : paragraph(model.title, { style: 'Title' });
  return { xml: `${title}${blocks.join('')}`, numberedLists: lists.length };
}

const HEADING_SIZES = [32, 28, 26, 24, 22, 21];

const STYLES = [
  `${XML_DECLARATION}<w:styles xmlns:w="${W}">`,
  '<w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Calibri" w:hAnsi="Calibri" w:eastAsia="Yu Gothic" w:cs="Calibri"/><w:sz w:val="21"/><w:szCs w:val="21"/><w:lang w:val="en-US" w:eastAsia="ja-JP"/></w:rPr></w:rPrDefault>',
  '<w:pPrDefault><w:pPr><w:spacing w:after="120" w:line="276" w:lineRule="auto"/></w:pPr></w:pPrDefault></w:docDefaults>',
  '<w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/><w:qFormat/></w:style>',
  '<w:style w:type="paragraph" w:styleId="Title"><w:name w:val="Title"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:qFormat/><w:pPr><w:spacing w:after="240"/></w:pPr><w:rPr><w:b/><w:sz w:val="40"/><w:szCs w:val="40"/></w:rPr></w:style>',
  ...HEADING_SIZES.map(
    (size, index) =>
      `<w:style w:type="paragraph" w:styleId="Heading${index + 1}"><w:name w:val="heading ${index + 1}"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:uiPriority w:val="9"/><w:qFormat/><w:pPr><w:keepNext/><w:spacing w:before="240" w:after="120"/><w:outlineLvl w:val="${index}"/></w:pPr><w:rPr><w:b/><w:sz w:val="${size}"/><w:szCs w:val="${size}"/></w:rPr></w:style>`,
  ),
  '<w:style w:type="paragraph" w:styleId="ListParagraph"><w:name w:val="List Paragraph"/><w:basedOn w:val="Normal"/><w:uiPriority w:val="34"/><w:qFormat/><w:pPr><w:spacing w:after="60"/></w:pPr></w:style>',
  '<w:style w:type="table" w:default="1" w:styleId="TableNormal"><w:name w:val="Normal Table"/><w:uiPriority w:val="99"/><w:semiHidden/><w:tblPr><w:tblInd w:w="0" w:type="dxa"/><w:tblCellMar><w:top w:w="0" w:type="dxa"/><w:left w:w="108" w:type="dxa"/><w:bottom w:w="0" w:type="dxa"/><w:right w:w="108" w:type="dxa"/></w:tblCellMar></w:tblPr></w:style>',
  `<w:style w:type="table" w:styleId="TableGrid"><w:name w:val="Table Grid"/><w:basedOn w:val="TableNormal"/><w:uiPriority w:val="39"/><w:pPr><w:spacing w:after="0" w:line="240" w:lineRule="auto"/></w:pPr><w:tblPr><w:tblBorders>${['top', 'left', 'bottom', 'right', 'insideH', 'insideV'].map((side) => `<w:${side} w:val="single" w:sz="4" w:space="0" w:color="auto"/>`).join('')}</w:tblBorders></w:tblPr></w:style>`,
  '</w:styles>',
].join('');

/** One abstract bullet list and one abstract numbered list; `numberedLists` instances restart at 1. */
function numbering(numberedLists) {
  const level = (format, text) =>
    `<w:lvl w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="${format}"/><w:lvlText w:val="${text}"/><w:lvlJc w:val="left"/><w:pPr><w:ind w:left="720" w:hanging="360"/></w:pPr></w:lvl>`;
  const numbered = Array.from(
    { length: numberedLists },
    (_, index) =>
      `<w:num w:numId="${BULLETS + 1 + index}"><w:abstractNumId w:val="1"/><w:lvlOverride w:ilvl="0"><w:startOverride w:val="1"/></w:lvlOverride></w:num>`,
  ).join('');
  return [
    `${XML_DECLARATION}<w:numbering xmlns:w="${W}">`,
    `<w:abstractNum w:abstractNumId="0"><w:multiLevelType w:val="singleLevel"/>${level('bullet', '•')}</w:abstractNum>`,
    `<w:abstractNum w:abstractNumId="1"><w:multiLevelType w:val="singleLevel"/>${level('decimal', '%1.')}</w:abstractNum>`,
    `<w:num w:numId="${BULLETS}"><w:abstractNumId w:val="0"/></w:num>${numbered}`,
    '</w:numbering>',
  ].join('');
}

/** The .docx bytes of a checked `docx` model. */
export function writeDocx(model) {
  const { xml, numberedLists } = body(model);
  const section = `<w:sectPr><w:pgSz w:w="${PAGE.width}" w:h="${PAGE.height}"/><w:pgMar w:top="${PAGE.margin}" w:right="${PAGE.margin}" w:bottom="${PAGE.margin}" w:left="${PAGE.margin}" w:header="720" w:footer="720" w:gutter="0"/></w:sectPr>`;
  return zip([
    [
      '[Content_Types].xml',
      contentTypes([
        ['word/document.xml', `${WORD}.document.main+xml`],
        ['word/styles.xml', `${WORD}.styles+xml`],
        ['word/numbering.xml', `${WORD}.numbering+xml`],
      ]),
    ],
    ['_rels/.rels', relationships([['officeDocument', 'word/document.xml']])],
    [
      'word/document.xml',
      `${XML_DECLARATION}<w:document xmlns:w="${W}"><w:body>${xml}${section}</w:body></w:document>`,
    ],
    [
      'word/_rels/document.xml.rels',
      relationships([
        ['styles', 'styles.xml'],
        ['numbering', 'numbering.xml'],
      ]),
    ],
    ['word/styles.xml', STYLES],
    ['word/numbering.xml', numbering(numberedLists)],
  ]);
}

// The office-writer model: what a .docx, .pptx or .xlsx is written from, and its validation.
//
// The model comes from an agent, so it is checked where it is read. A run's sandbox has Node and no
// npm packages, so the check is written by hand instead of with zod (ADR-0167 D3). Every issue is
// reported at once, each with the JSON path it is at, so the agent can repair the model in one step.

/** What one model may hold (ADR-0167 D4). Each is refused by name, never truncated. */
export const OFFICE_WRITER_LIMITS = Object.freeze({
  modelBytes: 8 * 1024 * 1024,
  textLength: 32_767,
  blocks: 5_000,
  listItems: 1_000,
  tableRows: 1_000,
  tableColumns: 32,
  slides: 200,
  bullets: 20,
  slideTableRows: 15,
  slideTableColumns: 8,
  sheets: 64,
  sheetColumns: 16_384,
  cells: 1_000_000,
  reportedIssues: 50,
});

export const OFFICE_FORMATS = Object.freeze(['docx', 'pptx', 'xlsx']);

/** Why nothing was written; `code` is the name an agent reports. */
export class OfficeWriterRefusal extends Error {
  constructor(code, message, issues = []) {
    super(message);
    this.name = 'OfficeWriterRefusal';
    this.code = code;
    this.issues = issues;
  }

  /** What the command prints on stderr. */
  toJSON() {
    return {
      error: this.code,
      message: this.message,
      ...(this.issues.length > 0 ? { issues: this.issues } : {}),
    };
  }
}

const isRecord = (value) => typeof value === 'object' && value !== null && !Array.isArray(value);
const at = (path, key) => (typeof key === 'number' ? `${path}[${key}]` : `${path}.${key}`);

/** False for a character XML 1.0 cannot carry: most C0 controls, a lone surrogate, U+FFFE/U+FFFF. */
function xmlSafe(text) {
  for (const char of text) {
    const code = char.codePointAt(0);
    if (code < 0x20 && code !== 0x09 && code !== 0x0a && code !== 0x0d) return false;
    if ((code >= 0xd800 && code <= 0xdfff) || code === 0xfffe || code === 0xffff) return false;
  }
  return true;
}

/** Collects issues while walking a model. Each check returns whether the value passed. */
class Checker {
  issues = [];

  fail(path, message) {
    this.issues.push({ path, message });
    return false;
  }

  /** An object with exactly the `required` keys and any of the `optional` ones. */
  fields(value, path, required, optional) {
    if (!isRecord(value)) return this.fail(path, 'must be an object');
    const known = new Set([...required, ...optional]);
    let ok = true;
    for (const key of Object.keys(value))
      if (!known.has(key)) ok = this.fail(at(path, key), 'is not a field of this object');
    for (const key of required)
      if (!Object.hasOwn(value, key)) ok = this.fail(at(path, key), 'is required');
    return ok;
  }

  /** A string; empty only when `allowEmpty`. */
  text(value, path, allowEmpty) {
    if (typeof value !== 'string') return this.fail(path, 'must be a string');
    if (!allowEmpty && value.trim() === '') return this.fail(path, 'must not be empty');
    if (value.length > OFFICE_WRITER_LIMITS.textLength)
      return this.fail(path, `is longer than ${OFFICE_WRITER_LIMITS.textLength} characters`);
    if (!xmlSafe(value)) return this.fail(path, 'holds a control character an Office file cannot');
    return true;
  }

  number(value, path) {
    if (typeof value !== 'number' || !Number.isFinite(value))
      return this.fail(path, 'must be a finite number');
    return true;
  }

  /** An array of 1..max items, each checked by `each`; past `max` the items are not walked. */
  list(value, path, max, each) {
    if (!Array.isArray(value)) return this.fail(path, 'must be an array');
    if (value.length === 0) return this.fail(path, 'must not be empty');
    if (value.length > max) return this.fail(path, `holds more than ${max} items`);
    let ok = true;
    value.forEach((item, index) => {
      if (!each(item, at(path, index))) ok = false;
    });
    return ok;
  }

  /** A table cell of a Word or slide table: text (may be empty) or a number. */
  tableCell(value, path) {
    return typeof value === 'number' ? this.number(value, path) : this.text(value, path, true);
  }

  /**
   * `{ header?, rows }` (and the `also` keys), every row as wide as the header, or as the first row
   * when there is none, and at most `columns` wide.
   */
  table(value, path, rows, columns, also) {
    if (!this.fields(value, path, [...also, 'rows'], ['header'])) return false;
    const width = (value.header ?? value.rows?.[0])?.length;
    const sized = (cells, cellsPath, each) =>
      this.list(cells, cellsPath, columns, each) &&
      (cells.length === width ||
        this.fail(cellsPath, `must have ${width} cells, as many as the header or the first row`));
    const header =
      value.header === undefined ||
      sized(value.header, at(path, 'header'), (cell, cellPath) => this.text(cell, cellPath, false));
    const body = this.list(value.rows, at(path, 'rows'), rows, (row, rowPath) =>
      sized(row, rowPath, (cell, cellPath) => this.tableCell(cell, cellPath)),
    );
    return header && body;
  }
}

// ---------- docx ----------

function block(check, value, path) {
  const type = isRecord(value) ? value.type : undefined;
  const { tableRows, tableColumns, listItems } = OFFICE_WRITER_LIMITS;
  switch (type) {
    case 'heading':
      return (
        check.fields(value, path, ['type', 'level', 'text'], []) &&
        ((Number.isInteger(value.level) && value.level >= 1 && value.level <= 6) ||
          check.fail(at(path, 'level'), 'must be an integer from 1 to 6')) &&
        check.text(value.text, at(path, 'text'), false)
      );
    case 'paragraph':
      return (
        check.fields(value, path, ['type', 'text'], []) &&
        check.text(value.text, at(path, 'text'), true)
      );
    case 'list':
      return (
        check.fields(value, path, ['type', 'items'], ['ordered']) &&
        (value.ordered === undefined ||
          typeof value.ordered === 'boolean' ||
          check.fail(at(path, 'ordered'), 'must be true or false')) &&
        check.list(value.items, at(path, 'items'), listItems, (item, itemPath) =>
          check.text(item, itemPath, false),
        )
      );
    case 'table':
      return check.table(value, path, tableRows, tableColumns, ['type']);
    default:
      return check.fail(at(path, 'type'), 'must be "heading", "paragraph", "list" or "table"');
  }
}

function docx(check, model) {
  return (
    check.fields(model, '$', ['format', 'blocks'], ['title']) &&
    (model.title === undefined || check.text(model.title, '$.title', false)) &&
    check.list(model.blocks, '$.blocks', OFFICE_WRITER_LIMITS.blocks, (value, path) =>
      block(check, value, path),
    )
  );
}

// ---------- pptx ----------

function slide(check, value, path) {
  const { bullets, slideTableRows, slideTableColumns } = OFFICE_WRITER_LIMITS;
  return (
    check.fields(value, path, ['title'], ['bullets', 'table']) &&
    check.text(value.title, at(path, 'title'), false) &&
    (value.bullets === undefined ||
      check.list(value.bullets, at(path, 'bullets'), bullets, (item, itemPath) =>
        check.text(item, itemPath, false),
      )) &&
    (value.table === undefined ||
      check.table(value.table, at(path, 'table'), slideTableRows, slideTableColumns, []))
  );
}

function pptx(check, model) {
  return (
    check.fields(model, '$', ['format', 'slides'], []) &&
    check.list(model.slides, '$.slides', OFFICE_WRITER_LIMITS.slides, (value, path) =>
      slide(check, value, path),
    )
  );
}

// ---------- xlsx ----------

/** True for `YYYY-MM-DD` naming a real day from 1900-03-01 (Excel's 1900 leap-year bug ends there). */
function isDate(text) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/u.exec(text);
  if (match === null || text < '1900-03-01') return false;
  const day = new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3])));
  return day.toISOString().slice(0, 10) === text;
}

function cell(check, value, path) {
  if (value === null || typeof value === 'boolean') return true;
  if (typeof value === 'number') return check.number(value, path);
  if (typeof value === 'string') return check.text(value, path, true);
  return (
    check.fields(value, path, ['date'], []) &&
    ((typeof value.date === 'string' && isDate(value.date)) ||
      check.fail(at(path, 'date'), 'must be a day written YYYY-MM-DD, from 1900-03-01'))
  );
}

const SHEET_NAME_FORBIDDEN = /[[\]:*?/\\\t\n\r]/u;

function sheetName(check, value, path, seen) {
  if (!check.text(value, path, false)) return false;
  if (value.length > 31) return check.fail(path, 'is longer than 31 characters');
  if (SHEET_NAME_FORBIDDEN.test(value) || value.startsWith("'") || value.endsWith("'"))
    return check.fail(
      path,
      "must not hold [ ] : * ? / \\, a tab or a line break, or start or end with '",
    );
  const key = value.toLowerCase();
  // Excel keeps "History" for its change-tracking sheet, in any case.
  if (key === 'history') return check.fail(path, 'is a name Excel reserves');
  if (seen.has(key)) return check.fail(path, 'names another sheet too (names ignore case)');
  seen.add(key);
  return true;
}

function xlsx(check, model) {
  const { sheets, sheetColumns, cells } = OFFICE_WRITER_LIMITS;
  const seen = new Set();
  let count = 0;
  const row = (value, path) =>
    check.list(value, path, sheetColumns, (item, itemPath) => {
      count += 1;
      return cell(check, item, itemPath);
    });
  return (
    check.fields(model, '$', ['format', 'sheets'], []) &&
    check.list(model.sheets, '$.sheets', sheets, (value, path) => {
      if (!check.fields(value, path, ['name', 'rows'], ['header'])) return false;
      const name = sheetName(check, value.name, at(path, 'name'), seen);
      const header = value.header === undefined || row(value.header, at(path, 'header'));
      const rows = check.list(value.rows, at(path, 'rows'), cells, row);
      return name && header && rows;
    }) &&
    (count <= cells || check.fail('$.sheets', `holds more than ${cells} cells`))
  );
}

// ---------- the model ----------

const FORMATS = { docx, pptx, xlsx };

/**
 * The model, checked. `format` names the file it is written to.
 *
 * @throws {OfficeWriterRefusal} `invalid_model`, with every issue found (the first
 *   `OFFICE_WRITER_LIMITS.reportedIssues`).
 */
export function parseModel(value) {
  const check = new Checker();
  const format = isRecord(value) ? value.format : undefined;
  if (OFFICE_FORMATS.includes(format)) FORMATS[format](check, value);
  else check.fail('$.format', 'must be "docx", "pptx" or "xlsx"');
  const { issues } = check;
  if (issues.length > 0)
    throw new OfficeWriterRefusal(
      'invalid_model',
      `the model has ${issues.length} issue${issues.length === 1 ? '' : 's'}; the first is ${issues[0].path} ${issues[0].message}`,
      issues.slice(0, OFFICE_WRITER_LIMITS.reportedIssues),
    );
  return value;
}

// An Office file is an Open Packaging Conventions package: a zip of XML parts, a content-type list
// and relationship parts. This writes one with node:zlib alone. A skill is installed on its own, so
// office-writer cannot import office-reader's zip code (ADR-0167 D6).
import { Buffer } from 'node:buffer';
import { crc32, deflateRawSync } from 'node:zlib'; // crc32: Node 22.2 and later

export const OOXML = 'http://schemas.openxmlformats.org';
export const XML_DECLARATION = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n';
const RELATIONSHIPS = `${OOXML}/package/2006/relationships`;
export const RELATIONSHIP_TYPE = `${OOXML}/officeDocument/2006/relationships`;

const ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' };

/** Text or an attribute value, escaped for XML. The model has already refused what XML cannot hold. */
export const escapeXml = (text) => String(text).replace(/[&<>"]/gu, (char) => ESCAPES[char]);

/** `[Content_Types].xml`: `xml` and `rels` by extension, and each named part's type. */
export function contentTypes(overrides) {
  const parts = overrides
    .map(([part, type]) => `<Override PartName="/${part}" ContentType="${type}"/>`)
    .join('');
  return `${XML_DECLARATION}<Types xmlns="${OOXML}/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/>${parts}</Types>`;
}

/** A relationship part; each target is `[type, target]` and gets `rId<n>` in order. */
export function relationships(targets) {
  const items = targets
    .map(
      ([type, target], index) =>
        `<Relationship Id="rId${index + 1}" Type="${RELATIONSHIP_TYPE}/${type}" Target="${target}"/>`,
    )
    .join('');
  return `${XML_DECLARATION}<Relationships xmlns="${RELATIONSHIPS}">${items}</Relationships>`;
}

// ---------- zip ----------

/** Little-endian fields, each `[bytes, value]` with `bytes` 2 or 4. */
function record(fields) {
  const buffer = Buffer.alloc(fields.reduce((total, [bytes]) => total + bytes, 0));
  let offset = 0;
  for (const [bytes, value] of fields) {
    offset =
      bytes === 2 ? buffer.writeUInt16LE(value, offset) : buffer.writeUInt32LE(value, offset);
  }
  return buffer;
}

const VERSION = 20; // 2.0: deflate
const UTF8_NAMES = 0x0800;
const DEFLATE = 8;
const DOS_DATE_1980_01_01 = 0x21; // a fixed stamp, so the same model always gives the same bytes

/** A zip of `parts` (`[name, text]`, in order), every part deflated, names in UTF-8. */
export function zip(parts) {
  const locals = [];
  const directory = [];
  let offset = 0;
  for (const [name, text] of parts) {
    const label = Buffer.from(name, 'utf8');
    const data = Buffer.from(text, 'utf8');
    const deflated = deflateRawSync(data);
    const common = [
      [2, UTF8_NAMES],
      [2, DEFLATE],
      [2, 0],
      [2, DOS_DATE_1980_01_01],
      [4, crc32(data)],
      [4, deflated.length],
      [4, data.length],
      [2, label.length],
      [2, 0],
    ];
    const local = record([[4, 0x04034b50], [2, VERSION], ...common]);
    locals.push(local, label, deflated);
    directory.push(
      record([
        [4, 0x02014b50],
        [2, VERSION],
        [2, VERSION],
        ...common,
        [2, 0],
        [2, 0],
        [2, 0],
        [4, 0],
        [4, offset],
      ]),
      label,
    );
    offset += local.length + label.length + deflated.length;
  }
  const central = Buffer.concat(directory);
  const end = record([
    [4, 0x06054b50],
    [2, 0],
    [2, 0],
    [2, parts.length],
    [2, parts.length],
    [4, central.length],
    [4, offset],
    [2, 0],
  ]);
  return Buffer.concat([...locals, central, end]);
}

// A .pptx from the office-writer model: 16:9 slides, each a title placeholder with bullets and a
// table below it, plus the slide master, layout and theme the format requires (ADR-0167 D6).
import {
  contentTypes,
  escapeXml,
  OOXML,
  RELATIONSHIP_TYPE,
  relationships,
  XML_DECLARATION,
  zip,
} from './package.mjs';

const PRESENTATION = 'application/vnd.openxmlformats-officedocument.presentationml';
const NAMESPACES = `xmlns:a="${OOXML}/drawingml/2006/main" xmlns:r="${RELATIONSHIP_TYPE}" xmlns:p="${OOXML}/presentationml/2006/main"`;

/** 16:9 in EMU, the area below the title, and the gap between bullets and a table. */
const SLIDE = { width: 12_192_000, height: 6_858_000 };
const MARGIN = 609_600;
const CONTENT = { x: MARGIN, y: 1_463_040, width: SLIDE.width - 2 * MARGIN, bottom: 6_400_800 };
const GAP = 182_880;
/** A table row's height when the rows fit: 0.45 inch, enough for one line at 14 pt. */
const ROW_HEIGHT = 411_480;

const GROUP =
  '<p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr>';

const xfrm = (tag, { x, y, width, height }) =>
  `<${tag}><a:off x="${x}" y="${y}"/><a:ext cx="${width}" cy="${height}"/></${tag}>`;

/** Runs of `text` at `size` hundredths of a point, a line break kept as an `<a:br/>`. */
function runs(text, size, bold) {
  const properties = `<a:rPr lang="ja-JP" sz="${size}"${bold ? ' b="1"' : ''}/>`;
  return String(text)
    .split(/\r\n|\r|\n/u)
    .map((line) => `<a:r>${properties}<a:t>${escapeXml(line)}</a:t></a:r>`)
    .join(`<a:br>${properties}</a:br>`);
}

function titleShape(title) {
  return `<p:sp><p:nvSpPr><p:cNvPr id="2" name="Title"/><p:cNvSpPr><a:spLocks noGrp="1"/></p:cNvSpPr><p:nvPr><p:ph type="title"/></p:nvPr></p:nvSpPr><p:spPr/><p:txBody><a:bodyPr/><a:lstStyle/><a:p>${runs(title, 3200, true)}</a:p></p:txBody></p:sp>`;
}

function bulletShape(bullets, area) {
  const paragraphs = bullets
    .map(
      (bullet) =>
        `<a:p><a:pPr marL="342900" indent="-342900"><a:buFont typeface="Arial"/><a:buChar char="•"/></a:pPr>${runs(bullet, 2000, false)}</a:p>`,
    )
    .join('');
  return `<p:sp><p:nvSpPr><p:cNvPr id="3" name="Bullets"/><p:cNvSpPr txBox="1"/><p:nvPr/></p:nvSpPr><p:spPr>${xfrm('a:xfrm', area)}<a:prstGeom prst="rect"><a:avLst/></a:prstGeom></p:spPr><p:txBody><a:bodyPr wrap="square"><a:normAutofit/></a:bodyPr><a:lstStyle/>${paragraphs}</p:txBody></p:sp>`;
}

const LINE = '<a:solidFill><a:srgbClr val="808080"/></a:solidFill>';
const BORDERS = ['lnL', 'lnR', 'lnT', 'lnB']
  .map((side) => `<a:${side} w="12700">${LINE}</a:${side}>`)
  .join('');

function tableShape({ header, rows }, area) {
  const all = header === undefined ? rows : [header, ...rows];
  const columns = all[0].length;
  const width = Math.floor(area.width / columns);
  const height = Math.min(ROW_HEIGHT, Math.floor(area.height / all.length));
  const cell = (value, bold) =>
    `<a:tc><a:txBody><a:bodyPr/><a:lstStyle/><a:p>${typeof value === 'number' ? '<a:pPr algn="r"/>' : ''}${runs(value, 1400, bold)}</a:p></a:txBody><a:tcPr>${BORDERS}${bold ? '<a:solidFill><a:srgbClr val="D9E2F3"/></a:solidFill>' : ''}</a:tcPr></a:tc>`;
  const tableRows = all
    .map(
      (cells, index) =>
        `<a:tr h="${height}">${cells.map((value) => cell(value, header !== undefined && index === 0)).join('')}</a:tr>`,
    )
    .join('');
  return `<p:graphicFrame><p:nvGraphicFramePr><p:cNvPr id="4" name="Table"/><p:cNvGraphicFramePr><a:graphicFrameLocks noGrp="1"/></p:cNvGraphicFramePr><p:nvPr/></p:nvGraphicFramePr>${xfrm('p:xfrm', { ...area, width: width * columns, height: height * all.length })}<a:graphic><a:graphicData uri="${OOXML}/drawingml/2006/table"><a:tbl><a:tblPr firstRow="${header === undefined ? 0 : 1}"/><a:tblGrid>${`<a:gridCol w="${width}"/>`.repeat(columns)}</a:tblGrid>${tableRows}</a:tbl></a:graphicData></a:graphic></p:graphicFrame>`;
}

/** Bullets take the area below the title, a table the rest; with both, the bullets take 40%. */
function slideXml({ title, bullets, table }) {
  const full = {
    x: CONTENT.x,
    y: CONTENT.y,
    width: CONTENT.width,
    height: CONTENT.bottom - CONTENT.y,
  };
  const split = bullets !== undefined && table !== undefined;
  const bulletArea = split ? { ...full, height: Math.floor(full.height * 0.4) } : full;
  const tableTop = split ? bulletArea.y + bulletArea.height + GAP : full.y;
  const tableArea = { ...full, y: tableTop, height: CONTENT.bottom - tableTop };
  const shapes = [
    titleShape(title),
    bullets === undefined ? '' : bulletShape(bullets, bulletArea),
    table === undefined ? '' : tableShape(table, tableArea),
  ].join('');
  return `${XML_DECLARATION}<p:sld ${NAMESPACES}><p:cSld><p:spTree>${GROUP}${shapes}</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>`;
}

const TITLE_PLACEHOLDER = (frame) =>
  `<p:sp><p:nvSpPr><p:cNvPr id="2" name="Title Placeholder"/><p:cNvSpPr><a:spLocks noGrp="1"/></p:cNvSpPr><p:nvPr><p:ph type="title"/></p:nvPr></p:nvSpPr><p:spPr>${frame}</p:spPr><p:txBody><a:bodyPr anchor="b"><a:normAutofit/></a:bodyPr><a:lstStyle/><a:p><a:endParaRPr lang="ja-JP"/></a:p></p:txBody></p:sp>`;

const MASTER = `${XML_DECLARATION}<p:sldMaster ${NAMESPACES}><p:cSld><p:bg><p:bgRef idx="1001"><a:schemeClr val="bg1"/></p:bgRef></p:bg><p:spTree>${GROUP}${TITLE_PLACEHOLDER(`${xfrm('a:xfrm', { x: MARGIN, y: 365_760, width: CONTENT.width, height: 914_400 })}<a:prstGeom prst="rect"><a:avLst/></a:prstGeom>`)}</p:spTree></p:cSld><p:clrMap bg1="lt1" tx1="dk1" bg2="lt2" tx2="dk2" accent1="accent1" accent2="accent2" accent3="accent3" accent4="accent4" accent5="accent5" accent6="accent6" hlink="hlink" folHlink="folHlink"/><p:sldLayoutIdLst><p:sldLayoutId id="2147483649" r:id="rId1"/></p:sldLayoutIdLst><p:txStyles><p:titleStyle><a:lvl1pPr><a:defRPr sz="3200" b="1"><a:solidFill><a:schemeClr val="tx1"/></a:solidFill><a:latin typeface="+mj-lt"/><a:ea typeface="+mj-ea"/></a:defRPr></a:lvl1pPr></p:titleStyle><p:bodyStyle><a:lvl1pPr><a:defRPr sz="2000"><a:solidFill><a:schemeClr val="tx1"/></a:solidFill><a:latin typeface="+mn-lt"/><a:ea typeface="+mn-ea"/></a:defRPr></a:lvl1pPr></p:bodyStyle><p:otherStyle><a:lvl1pPr><a:defRPr><a:latin typeface="+mn-lt"/><a:ea typeface="+mn-ea"/></a:defRPr></a:lvl1pPr></p:otherStyle></p:txStyles></p:sldMaster>`;

const LAYOUT = `${XML_DECLARATION}<p:sldLayout ${NAMESPACES} type="titleOnly" preserve="1"><p:cSld name="Title Only"><p:spTree>${GROUP}${TITLE_PLACEHOLDER('')}</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sldLayout>`;

const SCHEME_COLOURS = [
  ['dk1', '<a:sysClr val="windowText" lastClr="000000"/>'],
  ['lt1', '<a:sysClr val="window" lastClr="FFFFFF"/>'],
  ...[
    ['dk2', '44546A'],
    ['lt2', 'E7E6E6'],
    ['accent1', '4472C4'],
    ['accent2', 'ED7D31'],
    ['accent3', 'A5A5A5'],
    ['accent4', 'FFC000'],
    ['accent5', '5B9BD5'],
    ['accent6', '70AD47'],
    ['hlink', '0563C1'],
    ['folHlink', '954F72'],
  ].map(([name, rgb]) => [name, `<a:srgbClr val="${rgb}"/>`]),
];
const PLACEHOLDER_FILL = '<a:solidFill><a:schemeClr val="phClr"/></a:solidFill>';
const font = (latin, japanese) =>
  `<a:latin typeface="${latin}"/><a:ea typeface=""/><a:cs typeface=""/><a:font script="Jpan" typeface="${japanese}"/>`;

const THEME = [
  `${XML_DECLARATION}<a:theme xmlns:a="${OOXML}/drawingml/2006/main" name="Office Theme"><a:themeElements>`,
  `<a:clrScheme name="Office">${SCHEME_COLOURS.map(([name, colour]) => `<a:${name}>${colour}</a:${name}>`).join('')}</a:clrScheme>`,
  `<a:fontScheme name="Office"><a:majorFont>${font('Calibri Light', 'Yu Gothic Light')}</a:majorFont><a:minorFont>${font('Calibri', 'Yu Gothic')}</a:minorFont></a:fontScheme>`,
  `<a:fmtScheme name="Office"><a:fillStyleLst>${PLACEHOLDER_FILL.repeat(3)}</a:fillStyleLst>`,
  `<a:lnStyleLst>${`<a:ln w="6350">${PLACEHOLDER_FILL}</a:ln>`.repeat(3)}</a:lnStyleLst>`,
  `<a:effectStyleLst>${'<a:effectStyle><a:effectLst/></a:effectStyle>'.repeat(3)}</a:effectStyleLst>`,
  `<a:bgFillStyleLst>${PLACEHOLDER_FILL.repeat(3)}</a:bgFillStyleLst></a:fmtScheme>`,
  '</a:themeElements></a:theme>',
].join('');

/** The .pptx bytes of a checked `pptx` model. */
export function writePptx({ slides }) {
  const slideParts = slides.map((_, index) => `ppt/slides/slide${index + 1}.xml`);
  // rId1 master, rId2 theme, rId3 presentation properties, then the slides from rId4.
  const presentation = `${XML_DECLARATION}<p:presentation ${NAMESPACES} saveSubsetFonts="1"><p:sldMasterIdLst><p:sldMasterId id="2147483648" r:id="rId1"/></p:sldMasterIdLst><p:sldIdLst>${slides.map((_, index) => `<p:sldId id="${256 + index}" r:id="rId${4 + index}"/>`).join('')}</p:sldIdLst><p:sldSz cx="${SLIDE.width}" cy="${SLIDE.height}"/><p:notesSz cx="6858000" cy="9144000"/></p:presentation>`;
  return zip([
    [
      '[Content_Types].xml',
      contentTypes([
        ['ppt/presentation.xml', `${PRESENTATION}.presentation.main+xml`],
        ['ppt/presProps.xml', `${PRESENTATION}.presProps+xml`],
        ['ppt/slideMasters/slideMaster1.xml', `${PRESENTATION}.slideMaster+xml`],
        ['ppt/slideLayouts/slideLayout1.xml', `${PRESENTATION}.slideLayout+xml`],
        ['ppt/theme/theme1.xml', 'application/vnd.openxmlformats-officedocument.theme+xml'],
        ...slideParts.map((part) => [part, `${PRESENTATION}.slide+xml`]),
      ]),
    ],
    ['_rels/.rels', relationships([['officeDocument', 'ppt/presentation.xml']])],
    ['ppt/presentation.xml', presentation],
    [
      'ppt/_rels/presentation.xml.rels',
      relationships([
        ['slideMaster', 'slideMasters/slideMaster1.xml'],
        ['theme', 'theme/theme1.xml'],
        ['presProps', 'presProps.xml'],
        ...slideParts.map((part) => ['slide', part.slice('ppt/'.length)]),
      ]),
    ],
    ['ppt/presProps.xml', `${XML_DECLARATION}<p:presentationPr ${NAMESPACES}/>`],
    ['ppt/slideMasters/slideMaster1.xml', MASTER],
    [
      'ppt/slideMasters/_rels/slideMaster1.xml.rels',
      relationships([
        ['slideLayout', '../slideLayouts/slideLayout1.xml'],
        ['theme', '../theme/theme1.xml'],
      ]),
    ],
    ['ppt/slideLayouts/slideLayout1.xml', LAYOUT],
    [
      'ppt/slideLayouts/_rels/slideLayout1.xml.rels',
      relationships([['slideMaster', '../slideMasters/slideMaster1.xml']]),
    ],
    ['ppt/theme/theme1.xml', THEME],
    ...slides.flatMap((slide, index) => [
      [slideParts[index], slideXml(slide)],
      [
        `ppt/slides/_rels/slide${index + 1}.xml.rels`,
        relationships([['slideLayout', '../slideLayouts/slideLayout1.xml']]),
      ],
    ]),
  ]);
}

// A .xlsx from the office-writer model: sheets of typed cells, a bold and frozen header row, and
// dates stored as serial days with a date format (ADR-0167 D6).
import { contentTypes, escapeXml, OOXML, relationships, XML_DECLARATION, zip } from './package.mjs';

const MAIN = `${OOXML}/spreadsheetml/2006/main`;
const SHEET = 'application/vnd.openxmlformats-officedocument.spreadsheetml';

/** The cell formats `styles.xml` defines, by index. */
const HEADER_STYLE = 1;
const DATE_STYLE = 2;

const STYLES = [
  `${XML_DECLARATION}<styleSheet xmlns="${MAIN}">`,
  '<numFmts count="1"><numFmt numFmtId="164" formatCode="yyyy-mm-dd"/></numFmts>',
  '<fonts count="2"><font><sz val="11"/><name val="Calibri"/><family val="2"/></font><font><b/><sz val="11"/><name val="Calibri"/><family val="2"/></font></fonts>',
  '<fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills>',
  '<borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders>',
  '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>',
  '<cellXfs count="3"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/><xf numFmtId="164" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs>',
  '<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>',
  '</styleSheet>',
].join('');

/** 26 → 'AA'. */
function columnLetters(index) {
  let letters = '';
  for (let n = index + 1; n > 0; n = Math.floor((n - 1) / 26))
    letters = String.fromCharCode(65 + ((n - 1) % 26)) + letters;
  return letters;
}

/** Days since Excel's epoch, 1899-12-30, for a checked `YYYY-MM-DD` from 1900-03-01. */
function serialDay(date) {
  const [year, month, day] = date.split('-').map(Number);
  return (Date.UTC(year, month - 1, day) - Date.UTC(1899, 11, 30)) / 86_400_000;
}

/** Shared strings, each stored once, by first use; `count` is every cell that refers to one. */
function stringTable() {
  const indexes = new Map();
  let references = 0;
  return {
    index(text) {
      references += 1;
      if (!indexes.has(text)) indexes.set(text, indexes.size);
      return indexes.get(text);
    },
    xml() {
      const items = [...indexes.keys()]
        .map((text) => `<si><t xml:space="preserve">${escapeXml(text)}</t></si>`)
        .join('');
      return `${XML_DECLARATION}<sst xmlns="${MAIN}" count="${references}" uniqueCount="${indexes.size}">${items}</sst>`;
    },
  };
}

function cellXml(value, ref, strings, style) {
  const s = style === 0 ? '' : ` s="${style}"`;
  if (value === null) return '';
  if (typeof value === 'number') return `<c r="${ref}"${s}><v>${value}</v></c>`;
  if (typeof value === 'boolean') return `<c r="${ref}"${s} t="b"><v>${value ? 1 : 0}</v></c>`;
  if (typeof value === 'string')
    return `<c r="${ref}"${s} t="s"><v>${strings.index(value)}</v></c>`;
  return `<c r="${ref}" s="${DATE_STYLE}"><v>${serialDay(value.date)}</v></c>`;
}

/** Roughly how many characters wide a value shows; a full-width character counts two. */
function displayWidth(value) {
  if (value === null) return 0;
  if (typeof value === 'object') return 10;
  let width = 0;
  for (const char of String(value)) width += char.codePointAt(0) > 0xff ? 2 : 1;
  return width;
}

/** Each column as wide as its widest value, from 8 to 60 characters, so no date shows as ###. */
function columnsXml(all) {
  const widths = [];
  for (const cells of all)
    cells.forEach((value, column) => {
      widths[column] = Math.max(widths[column] ?? 8, Math.min(60, displayWidth(value) + 2));
    });
  const columns = widths
    .map(
      (width, column) =>
        `<col min="${column + 1}" max="${column + 1}" width="${width}" customWidth="1"/>`,
    )
    .join('');
  return `<cols>${columns}</cols>`;
}

function sheetXml({ header, rows }, strings) {
  const all = header === undefined ? rows : [header, ...rows];
  const data = all
    .map((cells, row) => {
      const style = header !== undefined && row === 0 ? HEADER_STYLE : 0;
      const xml = cells
        .map((value, column) =>
          cellXml(value, `${columnLetters(column)}${row + 1}`, strings, style),
        )
        .join('');
      return `<row r="${row + 1}">${xml}</row>`;
    })
    .join('');
  const view =
    header === undefined
      ? '<sheetView workbookViewId="0"/>'
      : '<sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/><selection pane="bottomLeft"/></sheetView>';
  return `${XML_DECLARATION}<worksheet xmlns="${MAIN}"><sheetViews>${view}</sheetViews>${columnsXml(all)}<sheetData>${data}</sheetData></worksheet>`;
}

/** The .xlsx bytes of a checked `xlsx` model. */
export function writeXlsx({ sheets }) {
  const strings = stringTable();
  const sheetParts = sheets.map((sheet, index) => [
    `xl/worksheets/sheet${index + 1}.xml`,
    sheetXml(sheet, strings),
  ]);
  const workbook = `${XML_DECLARATION}<workbook xmlns="${MAIN}" xmlns:r="${OOXML}/officeDocument/2006/relationships"><bookViews><workbookView/></bookViews><sheets>${sheets.map((sheet, index) => `<sheet name="${escapeXml(sheet.name)}" sheetId="${index + 1}" r:id="rId${index + 1}"/>`).join('')}</sheets></workbook>`;
  return zip([
    [
      '[Content_Types].xml',
      contentTypes([
        ['xl/workbook.xml', `${SHEET}.sheet.main+xml`],
        ['xl/styles.xml', `${SHEET}.styles+xml`],
        ['xl/sharedStrings.xml', `${SHEET}.sharedStrings+xml`],
        ...sheetParts.map(([part]) => [part, `${SHEET}.worksheet+xml`]),
      ]),
    ],
    ['_rels/.rels', relationships([['officeDocument', 'xl/workbook.xml']])],
    ['xl/workbook.xml', workbook],
    [
      'xl/_rels/workbook.xml.rels',
      relationships([
        ...sheetParts.map(([part]) => ['worksheet', part.slice('xl/'.length)]),
        ['styles', 'styles.xml'],
        ['sharedStrings', 'sharedStrings.xml'],
      ]),
    ],
    ['xl/styles.xml', STYLES],
    ...sheetParts,
    ['xl/sharedStrings.xml', strings.xml()],
  ]);
}

#!/usr/bin/env node
// Write a .docx, .pptx or .xlsx from an office-writer model, with Node alone.
//
//   node write.mjs <model.json> <out.docx|out.pptx|out.xlsx>   → { "written": "<out>", "bytes": n }
//
// The model's `format` must match the output's extension. The output's folder is created, and an
// output that already exists is refused, so an approved call never replaces a file the approver did
// not see (ADR-0167 D5). A refusal exits 1 with `{ "error", "message", "issues"? }` on stderr; a
// wrong number of arguments exits 2.
import {
  closeSync,
  fstatSync,
  mkdirSync,
  openSync,
  readFileSync,
  unlinkSync,
  writeFileSync,
} from 'node:fs';
import { dirname, extname } from 'node:path';
import process from 'node:process';
import { pathToFileURL } from 'node:url';

import { writeDocx } from './lib/docx.mjs';
import {
  OFFICE_FORMATS,
  OFFICE_WRITER_LIMITS,
  OfficeWriterRefusal,
  parseModel,
} from './lib/model.mjs';
import { writePptx } from './lib/pptx.mjs';
import { writeXlsx } from './lib/xlsx.mjs';

const WRITERS = { docx: writeDocx, pptx: writePptx, xlsx: writeXlsx };

/** The bytes of the file a checked model describes. */
export function buildOfficeFile(model) {
  return WRITERS[model.format](model);
}

/** The model file's text, its size checked on the descriptor it is then read from. */
function modelText(file) {
  const unreadable = () => new OfficeWriterRefusal('unreadable_model', `${file} is not a file`);
  let fd;
  try {
    fd = openSync(file, 'r');
  } catch {
    throw unreadable();
  }
  try {
    const stat = fstatSync(fd);
    if (!stat.isFile()) throw unreadable();
    if (stat.size > OFFICE_WRITER_LIMITS.modelBytes)
      throw new OfficeWriterRefusal(
        'model_too_large',
        `${file} is ${stat.size} bytes; at most ${OFFICE_WRITER_LIMITS.modelBytes} are read`,
      );
    return readFileSync(fd, 'utf8');
  } finally {
    closeSync(fd);
  }
}

function readModel(file) {
  const text = modelText(file);
  let value;
  try {
    value = JSON.parse(text);
  } catch (error) {
    throw new OfficeWriterRefusal('invalid_json', `${file} is not JSON: ${error.message}`);
  }
  return parseModel(value);
}

/**
 * Creates the output's folder and the file, never replacing one that exists. A write that fails
 * after the file was created removes it, so no truncated file is left behind.
 *
 * @throws {OfficeWriterRefusal} `output_exists` or `output_not_writable`.
 */
export function saveNewFile(output, bytes) {
  const unwritable = (error) =>
    new OfficeWriterRefusal(
      'output_not_writable',
      `${output} could not be written (${error.code})`,
    );
  try {
    mkdirSync(dirname(output), { recursive: true });
  } catch (error) {
    throw unwritable(error);
  }
  let fd;
  try {
    fd = openSync(output, 'wx');
  } catch (error) {
    throw error.code === 'EEXIST'
      ? new OfficeWriterRefusal('output_exists', `${output} exists; write to a new name`)
      : unwritable(error);
  }
  let failure;
  try {
    writeFileSync(fd, bytes);
  } catch (error) {
    failure = error;
  } finally {
    closeSync(fd);
  }
  if (failure !== undefined) {
    unlinkSync(output);
    throw unwritable(failure);
  }
}

/**
 * Reads, checks and writes. Nothing is written unless the whole model is valid.
 *
 * @throws {OfficeWriterRefusal}
 */
export function writeOfficeFile(modelFile, output) {
  const extension = extname(output).slice(1);
  if (!OFFICE_FORMATS.includes(extension))
    throw new OfficeWriterRefusal(
      'extension_mismatch',
      `${output} must end in .docx, .pptx or .xlsx`,
    );
  const model = readModel(modelFile);
  if (model.format !== extension)
    throw new OfficeWriterRefusal(
      'extension_mismatch',
      `the model is a ${model.format}, but ${output} ends in .${extension}`,
    );
  const bytes = buildOfficeFile(model);
  saveNewFile(output, bytes);
  return { written: output, bytes: bytes.length };
}

const USAGE = 'usage: node write.mjs <model.json> <out.docx|out.pptx|out.xlsx>\n';

/** The command: its exit code, with the result on `io.stdout` and a refusal on `io.stderr`. */
export function main(args, io) {
  if (args.length !== 2) {
    io.stderr.write(USAGE);
    return 2;
  }
  try {
    io.stdout.write(`${JSON.stringify(writeOfficeFile(args[0], args[1]))}\n`);
    return 0;
  } catch (error) {
    if (!(error instanceof OfficeWriterRefusal)) throw error;
    io.stderr.write(`${JSON.stringify(error)}\n`);
    return 1;
  }
}

if (import.meta.url === pathToFileURL(String(process.argv[1])).href)
  process.exitCode = main(process.argv.slice(2), process);
